    @_mutmut_mutated(mutants_xǁComplianceServiceǁget_project_evaluation_history__mutmut)
    def get_project_evaluation_history(
        self,
        db: Session,
        project_id: UUID,
    ) -> list[dict]:
        """Return evaluation history with compliance results grouped by run."""

        project = get_project(
            db,
            project_id,
        )

        if project is None:
            raise ValueError("Project not found")

        evaluation_runs = get_project_evaluation_runs(
            db=db,
            project_id=project_id,
        )

        results_by_run = get_project_evaluation_results_by_run(
            db=db,
            project_id=project_id,
        )

        history = []

        for evaluation_run in evaluation_runs:
            history.append(
                {
                    "evaluation_run": evaluation_run,
                    "results": results_by_run.get(
                        evaluation_run.id,
                        [],
                    ),
                }
            )

        return history

